<?php
namespace Tests\Feature;
use App\Models\Order;use App\Models\Products;use App\Models\User;use App\Services\PaymentService;use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Support\Facades\Hash;use Tests\TestCase;
class InventoryBusinessModulesTest extends TestCase {use RefreshDatabase;private function manager():User{return User::create(['name'=>'Manager','email'=>'manager-modules@example.test','password'=>Hash::make('password'),'role'=>'manager','is_active'=>true]);}public function test_payment_service_updates_partial_payment_status():void{$manager=$this->manager();$order=Order::create(['order_number'=>'SO-TEST-1','created_by'=>$manager->id,'status'=>'confirmed','payment_status'=>'unpaid','delivery_status'=>'pending','subtotal'=>100000,'discount_amount'=>0,'tax_amount'=>0,'total_amount'=>100000,'order_date'=>now()->toDateString()]);app(PaymentService::class)->record($order,40000,'cash');$this->assertDatabaseHas('payments',['order_id'=>$order->id,'amount'=>40000,'status'=>'paid']);$this->assertSame('partial',$order->fresh()->payment_status);}public function test_payment_cannot_exceed_outstanding_balance():void{$this->expectException(\Symfony\Component\HttpKernel\Exception\HttpException::class);$manager=$this->manager();$order=Order::create(['order_number'=>'SO-TEST-2','created_by'=>$manager->id,'status'=>'confirmed','payment_status'=>'unpaid','delivery_status'=>'pending','subtotal'=>10000,'discount_amount'=>0,'tax_amount'=>0,'total_amount'=>10000,'order_date'=>now()->toDateString()]);app(PaymentService::class)->record($order,10001,'cash');}public function test_barcode_is_unique():void{$manager=$this->manager();$this->actingAs($manager);Products::create(['product_name'=>'Scanner Item','sku'=>'SKU-1','barcode'=>'BC-1','product_price'=>1000,'stock_quantity'=>2,'reorder_level'=>1,'is_active'=>true]);$this->assertDatabaseHas('products',['barcode'=>'BC-1']);}}
